// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.ttsimport com.roshan.persona.brain.context.AmbientSnapshotimport com.roshan.persona.brain.context.UserActivity/** * NOUS — Activity-Aware Prosody (v2 Review 2 Upgrade). * * Adapts TTS prosody based on the user's physical activity. This is critical * for natural conversation — NOUS shouldn't speak the same way when the user * is running (need louder, faster, concise) vs sleeping (need whisper, slow, * minimal). * * ## Activities and Prosody * *   - **RUNNING / IN_VEHICLE**: louder (1.5x), faster (1.2x), concise (50 tokens max). *     User is moving — can't focus on long responses. * *   - **WALKING**: normal volume, normal rate, normal length (100 tokens). *     User can hear normally but is in motion. * *   - **STILL**: normal volume, normal rate, normal length (200 tokens). *     Default — user is sitting/standing. * *   - **ON_BICYCLE**: louder (1.3x), faster (1.1x), concise (80 tokens). *     Wind noise + motion → need louder, shorter. * *   - **SLEEPING**: whisper (0.3x volume), slower (0.7x), minimal (20 tokens). *     Critical: detected via 1 AM + face-down + dark room (not just activity). * *   - **IN_MEETING**: text-only (0 volume), no TTS. Brain routes to notification. * *   - **UNKNOWN**: default prosody (no override). * * ## Detection * * User activity is detected via Android's ActivityRecognitionClient (Google * Play Services). The brain (Module 2) receives activity updates and includes * them in the AmbientSnapshot. * * For SLEEPING detection, we use a heuristic: *   - Time of day (11 PM - 6 AM) *   - Device is face-down (proximity sensor covered) *   - Screen is off *   - No movement for 30+ minutes * * ## Privacy * *   - Activity data stays on-device (Google Play Services processes locally) *   - User can disable activity detection in Privacy Settings (default OFF) *   - When disabled, NOUS uses STILL prosody (no activity-based adjustment) * * @see <a href="docs/strategy/module-5-strategy-v2.md">§21 Activity-Aware Prosody — Review 2 Upgrade</a> */class ActivityAwareProsody {    /**     * Compute prosody override based on user activity + ambient context.     *     * @param activity detected user activity (or null if unavailable)     * @param ambient  ambient snapshot (light, proximity, time-of-day) — used     *                 to refine SLEEPING detection. Null if unavailable.     * @return prosody override to apply on top of emotion-based prosody     */    fun computeOverride(        activity: UserActivity?,        ambient: AmbientSnapshot? = null,    ): ProsodyOverride {        if (activity == null) return ProsodyOverride.DEFAULT        // Refine STILL → SLEEPING using ambient context.        val effectiveActivity = refineActivity(activity, ambient)        return when (effectiveActivity) {            UserActivity.RUNNING, UserActivity.IN_VEHICLE -> ProsodyOverride(                volumeMultiplier = 1.5f,                rateMultiplier = 1.2f,                maxTokens = 50,  // concise                whisper = false,                activityReason = "User is moving (${effectiveActivity.name})",            )            UserActivity.ON_BICYCLE -> ProsodyOverride(                volumeMultiplier = 1.3f,                rateMultiplier = 1.1f,                maxTokens = 80,                whisper = false,                activityReason = "User is cycling (wind noise)",            )            UserActivity.WALKING -> ProsodyOverride(                volumeMultiplier = 1.0f,                rateMultiplier = 1.0f,                maxTokens = 100,                whisper = false,                activityReason = "User is walking",            )            UserActivity.STILL -> ProsodyOverride(                volumeMultiplier = 1.0f,                rateMultiplier = 1.0f,                maxTokens = 200,                whisper = false,                activityReason = "User is stationary",            )            UserActivity.SLEEPING -> ProsodyOverride(                volumeMultiplier = 0.3f,                rateMultiplier = 0.7f,                maxTokens = 20,  // minimal                whisper = true,  // whisper mode                activityReason = "User is sleeping (whisper mode)",            )            UserActivity.IN_MEETING -> ProsodyOverride(                volumeMultiplier = 0.0f,  // silent                rateMultiplier = 1.0f,                maxTokens = 0,  // text only                whisper = false,                textOnly = true,                activityReason = "User is in a meeting (text only)",            )            UserActivity.UNKNOWN -> ProsodyOverride.DEFAULT        }    }    /**     * Refine the activity using ambient signals.     *     * - STILL + dark + 11 PM–6 AM → SLEEPING     * - STILL + ringer silent + calendar busy → IN_MEETING     */    private fun refineActivity(        activity: UserActivity,        ambient: AmbientSnapshot?,    ): UserActivity {        if (ambient == null) return activity        if (activity == UserActivity.STILL) {            if (ambient.isLikelySleeping()) return UserActivity.SLEEPING            if (ambient.isLikelyInMeeting()) return UserActivity.IN_MEETING        }        return activity    }}/** * Prosody override from activity detection. * * Applied on top of emotion-based prosody. Multipliers are combined * (emotion × activity) to produce the final [ProsodyProfile]. * * @see ActivityAwareProsody * @see ProsodyComputer */data class ProsodyOverride(    /** Volume multiplier (1.0 = normal, >1 = louder, <1 = quieter). */    val volumeMultiplier: Float,    /** Rate multiplier (1.0 = normal, >1 = faster, <1 = slower). */    val rateMultiplier: Float,    /** Maximum tokens to synthesize (concise responses for active users). */    val maxTokens: Int,    /** Whether to use whisper mode (sleeping). */    val whisper: Boolean,    /** Whether to suppress TTS entirely (text only, for meetings). */    val textOnly: Boolean = false,    /** Human-readable reason for this override (for diagnostics). */    val activityReason: String,) {    init {        require(volumeMultiplier in 0.0f..2.0f) { "volumeMultiplier $volumeMultiplier out of [0.0, 2.0]" }        require(rateMultiplier in 0.5f..2.0f) { "rateMultiplier $rateMultiplier out of [0.5, 2.0]" }        require(maxTokens in 0..1000) { "maxTokens $maxTokens out of [0, 1000]" }    }    companion object {        /** Default override (no change from emotion-based prosody). */        val DEFAULT = ProsodyOverride(            volumeMultiplier = 1.0f,            rateMultiplier = 1.0f,            maxTokens = 200,            whisper = false,            activityReason = "No activity override",        )    }}